mapper.select:
WITH target_branches AS ( SELECT id, branch_name FROM bbx_energy_branch WHERE branch_type = #{branchType} AND tenant_id = #{tenantId} AND (
parent_id IS NULL
parent_id = #{branchId}
) ), last_in_range AS ( SELECT device_id, reading_value FROM ( SELECT device_id, reading_value, ROW_NUMBER() OVER (PARTITION BY device_id ORDER BY count_time DESC) AS rn FROM bbx_meter_person_record_count WHERE count_time BETWEEN #{startTime} AND #{endTime} AND tenant_id = #{tenantId} ) t WHERE rn = 1 ), last_before_range AS ( SELECT device_id, reading_value FROM ( SELECT device_id, reading_value, ROW_NUMBER() OVER (PARTITION BY device_id ORDER BY count_time DESC) AS rn FROM bbx_meter_person_record_count WHERE count_time < #{startTime} AND tenant_id = #{tenantId} ) t WHERE rn = 1 ), first_in_range AS ( SELECT device_id, reading_value FROM ( SELECT device_id, reading_value, ROW_NUMBER() OVER (PARTITION BY device_id ORDER BY count_time ASC) AS rn FROM bbx_meter_person_record_count WHERE count_time BETWEEN #{startTime} AND #{endTime} AND tenant_id = #{tenantId} ) t WHERE rn = 1 ), device_energy AS ( SELECT l.device_id, l.reading_value - COALESCE(b.reading_value, f.reading_value, l.reading_value) AS energy FROM last_in_range l LEFT JOIN last_before_range b ON l.device_id = b.device_id LEFT JOIN first_in_range f ON l.device_id = f.device_id ), branch_energy AS ( SELECT bd.branch_id, SUM(COALESCE(de.energy, 0)) AS total_energy FROM bbx_branch_device bd LEFT JOIN device_energy de ON bd.device_id = de.device_id WHERE bd.branch_id IN (SELECT id FROM target_branches) AND bd.tenant_id = #{tenantId} GROUP BY bd.branch_id ) SELECT tb.id AS id, tb.branch_name AS branchName, COALESCE(be.total_energy, 0) AS electricity, CASE WHEN EXISTS ( SELECT 1 FROM bbx_energy_branch child WHERE child.parent_id = tb.id AND child.tenant_id = #{tenantId} AND child.branch_type = #{branchType} ) THEN 1 ELSE 0 END AS hasChildren FROM target_branches tb LEFT JOIN branch_energy be ON tb.id = be.branch_id ORDER BY tb.id
